const body = $input.first().json.body || {};
const addr = String((body.input || {}).address || '').trim();
if (!/^0x[a-fA-F0-9]{40}$/.test(addr)) {
  throw new Error('Send {"input":{"address":"0x..."}} with a 20-byte hex address');
}
return [{ json: { address: addr } }];

// Fetched as TEXT deliberately. n8n splits a JSON array response into one
// item per element, which would turn a 120 entry list into 120 workflow items
// and lose the address we are checking. Parsing it here keeps it one item.
const raw = $input.first().json.data ?? $input.first().json;
const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
const address = $('Read address').first().json.address;
const want = address.toLowerCase();

const hit = arr.some((a) => String(a).toLowerCase() === want);

// listSize and checkedAt are the point. A no_match is only worth anything if
// you can say what it was checked against and when.
return [{ json: { output: {
  address,
  verdict: hit ? 'MATCH' : 'no_match',
  sanctioned: hit,
  listSize: arr.length,
  source: 'OFAC SDN digital currency addresses (ETH)',
  sourceUrl: 'https://sanctionslist.ofac.treas.gov',
  checkedAt: new Date().toISOString(),
} } }];
